"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["93315"],{92911(e){e.exports=JSON.parse('{"tag":{"label":"Genetics","permalink":"/docs/tags/genetics","allTagsPath":"/docs/tags","count":10,"items":[{"id":"guinea-pigs/illnesses-and-conditions/fetal-arrhythmia","title":"Fetal Arrhythmia in Guinea Pigs: What It Is and What It Means","description":"Pregnancy in guinea pigs can be a delicate time, requiring close monitoring and appropriate veterinary care. One rare but important condition that can arise is fetal arrhythmia, an irregular heartbeat detected in a developing fetus. While unsettling to hear about, understanding this condition can help owners and rescues make informed decisions.","permalink":"/docs/guinea-pigs/illnesses-and-conditions/fetal-arrhythmia"},{"id":"Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds","title":"Know Your Chinchilla Breeds","description":"An overview of chinchilla species and the wide variety of color mutations found in pet chinchillas.","permalink":"/docs/Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds"},{"id":"guinea-pigs/breeds-and-genetics/know-your-guinea-pig-breeds","title":"Know Your Guinea Pig Breeds","description":"From the sleek and smooth to the curly and long-haired, guinea pigs come in a wonderful variety of breeds, each with its own unique look and grooming needs. While personality is individual, some...","permalink":"/docs/guinea-pigs/breeds-and-genetics/know-your-guinea-pig-breeds"},{"id":"Rabbits/illnesses-and-conditions/maxfactor","title":"Max Factor Rabbits","description":"Max Factor rabbits are a rare and unique type of rabbit affected by a genetic mutation that results in unusual physical characteristics. These rabbits have striking appearances due to differences in their fur and limbs. It\u2019s said that the condition is named after a rabbit named Max who was known to have the condition, but not much is known about the defect or its origin. However, the mutation also affects their health and mobility, creating both challenges and specific care needs. Here\u2019s everything you need to know about Max Factor rabbits, from their characteristics to the ethics of breeding them.","permalink":"/docs/Rabbits/illnesses-and-conditions/maxfactor"},{"id":"general-care/health-and-medical/microphthalmia","title":"Microphthalmia in Small Pets","description":"A comprehensive guide to microphthalmia (abnormally small eyes) in small pets, covering its genetic causes, species-specific presentations in rabbits, ferrets, hamsters, guinea pigs, and rats, and how to manage affected animals.","permalink":"/docs/general-care/health-and-medical/microphthalmia"},{"id":"guinea-pigs/breeds-and-genetics/satinsyndrome","title":"Satin Syndrome in Guinea Pigs","description":"Satin guinea pig","permalink":"/docs/guinea-pigs/breeds-and-genetics/satinsyndrome"},{"id":"guinea-pigs/illnesses-and-conditions/clubbed-feet","title":"Understanding Clubbed Feet and Limb Deformities in Guinea Pigs","description":"Guinea pigs are known for their sweet personalities and unique charm\u2014but some arrive into rescue with visible physical challenges, including limb deformities commonly referred to as \\"clubbed feet.\\" Understanding this condition is key to providing these special-needs pigs with the quality of life they deserve.","permalink":"/docs/guinea-pigs/illnesses-and-conditions/clubbed-feet"},{"id":"guinea-pigs/breeds-and-genetics/coat-color-genetics","title":"Understanding Guinea Pig Coat Color Genetics","description":"Guinea pigs are known for their stunning diversity of coat colors and patterns, from solid black to intricate brindles and dalmatians. This variety isn\'t random; it\'s the result of a fascinating and complex world of genetics. Understanding the basics of coat color inheritance is not only interesting for curious owners but is also critical for responsible breeding and rescue advocacy to prevent serious genetic health problems.","permalink":"/docs/guinea-pigs/breeds-and-genetics/coat-color-genetics"},{"id":"guinea-pigs/breeds-and-genetics/lethalwhite","title":"Understanding Lethal White Guinea Pigs","description":"Guinea pigs are beloved companions known for their sweet nature, vocal personalities, and varied appearances. But within the world of guinea pig care, there\u2019s a little-known and serious condition that deserves more awareness\u2014lethal white syndrome.","permalink":"/docs/guinea-pigs/breeds-and-genetics/lethalwhite"},{"id":"Rats/breeds-and-genetics/hairless-rats","title":"What to Know About Hairless Rats","description":"A guide to caring for hairless rats, explaining their genetic background, unique care needs regarding temperature, diet, and skin health, and common health issues.","permalink":"/docs/Rats/breeds-and-genetics/hairless-rats"}],"unlisted":false}}')}}]);